1	#!/usr/bin/env -S deno run --allow-env --allow-net
2	/**
3	 * T8.1: Seed data and disclosure.
4	 *
5	 * Seeds the demo history that no run of real calls produced. The seed carries
6	 * one item ("the dentist") with three call runs on three separate local dates,
7	 * each with an item_mentions row linking the item to the run. Optionally seeds
8	 * two more items with fewer mentions so Today does not look staged.
9	 *
10	 * Usage:
11	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address>
12	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address> --apply
13	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address> --remove
14	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address> --demo-date 2026-09-14
15	 *
16	 * Flags:
17	 *   --email <address>       The account to seed. Must have a profiles row.
18	 *   --demo-date <YYYY-MM-DD> The date the 34 days count to. Defaults to today
19	 *                            in the profile's timezone.
20	 *   --apply                 Write rows. Without this flag, only the plan prints.
21	 *   --remove                Delete every seeded row for the account.
22	 *   --i-confirmed-dry-run   Required for --apply against a non-local URL.
23	 *
24	 * Reaches Supabase only through ORMA_API_URL with SUPABASE_SERVICE_ROLE_KEY,
25	 * because the admin API rejects the new-format secret key.
26	 */
27	
28	import { createClient } from "npm:@supabase/supabase-js@2";
29	
30	// ---------------------------------------------------------------------------
31	// Environment
32	// ---------------------------------------------------------------------------
33	
34	function requireEnv(name: string): string {
35	  const value = Deno.env.get(name);
36	  if (!value) {
37	    console.error(`Missing required environment variable: ${name}`);
38	    Deno.exit(1);
39	  }
40	  return value;
41	}
42	
43	const ORMA_API_URL = requireEnv("ORMA_API_URL").replace(/\/+$/, "");
44	const SERVICE_ROLE_KEY = requireEnv("SUPABASE_SERVICE_ROLE_KEY");
45	
46	// ---------------------------------------------------------------------------
47	// CLI arguments
48	// ---------------------------------------------------------------------------
49	
50	function parseArgs(args: string[]) {
51	  let email: string | undefined;
52	  let demoDate: string | undefined;
53	  let apply = false;
54	  let remove = false;
55	  let confirmedDryRun = false;
56	
57	  for (let i = 0; i < args.length; i++) {
58	    switch (args[i]) {
59	      case "--email":
60	        email = args[++i];
61	        break;
62	      case "--demo-date":
63	        demoDate = args[++i];
64	        break;
65	      case "--apply":
66	        apply = true;
67	        break;
68	      case "--remove":
69	        remove = true;
70	        break;
71	      case "--i-confirmed-dry-run":
72	        confirmedDryRun = true;
73	        break;
74	      default:
75	        console.error(`Unknown flag: ${args[i]}`);
76	        Deno.exit(1);
77	    }
78	  }
79	
80	  if (!email) {
81	    console.error("--email is required.");
82	    Deno.exit(1);
83	  }
84	
85	  if (apply && remove) {
86	    console.error("Cannot pass both --apply and --remove.");
87	    Deno.exit(1);
88	  }
89	
90	  return { email, demoDate, apply, remove, confirmedDryRun };
91	}
92	
93	const flags = parseArgs(Deno.args);
94	
95	// ---------------------------------------------------------------------------
96	// Safety: refuse --apply against non-local without --i-confirmed-dry-run
97	// ---------------------------------------------------------------------------
98	
99	function isLocalUrl(url: string): boolean {
100	  try {
101	    const parsed = new URL(url);
102	    return parsed.hostname === "127.0.0.1" ||
103	      parsed.hostname === "localhost" ||
104	      parsed.hostname === "0.0.0.0" ||
105	      parsed.hostname === "[::1]";
106	  } catch {
107	    return false;
108	  }
109	}
110	
111	if (flags.apply && !isLocalUrl(ORMA_API_URL) && !flags.confirmedDryRun) {
112	  console.error(
113	    "Refusing --apply against a non-local URL without --i-confirmed-dry-run.",
114	  );
115	  console.error(`ORMA_API_URL is ${ORMA_API_URL}`);
116	  Deno.exit(1);
117	}
118	
119	// ---------------------------------------------------------------------------
120	// Supabase client
121	// ---------------------------------------------------------------------------
122	
123	const supabase = createClient(ORMA_API_URL, SERVICE_ROLE_KEY, {
124	  auth: {
125	    persistSession: false,
126	    autoRefreshToken: false,
127	    detectSessionInUrl: false,
128	  },
129	});
130	
131	// ---------------------------------------------------------------------------
132	// Lookup the profile by email
133	// ---------------------------------------------------------------------------
134	
135	async function lookupProfile(email: string) {
136	  // Use the auth admin API to find the user by email.
137	  const { data: userData, error: userError } = await supabase.auth.admin
138	    .listUsers();
139	  if (userError) {
140	    console.error("Failed to list users:", userError.message);
141	    Deno.exit(1);
142	  }
143	  const user = userData.users.find((u) =>
144	    u.email?.toLowerCase() === email.toLowerCase()
145	  );
146	  if (!user) {
147	    console.error(`No auth.users row found for email: ${email}`);
148	    Deno.exit(1);
149	  }
150	
151	  const { data: profile, error: profileError } = await supabase
152	    .from("profiles")
153	    .select("*")
154	    .eq("id", user.id)
155	    .single();
156	  if (profileError || !profile) {
157	    console.error(
158	      `No profiles row found for user ${user.id}:`,
159	      profileError?.message,
160	    );
161	    Deno.exit(1);
162	  }
163	
164	  return profile as {
165	    id: string;
166	    display_name: string;
167	    timezone: string;
168	    phone_e164: string | null;
169	  };
170	}
171	
172	// ---------------------------------------------------------------------------
173	// Stable UUIDs from a seed namespace
174	// ---------------------------------------------------------------------------
175	
176	// Deterministic UUIDs so reruns produce the same rows.
177	// Uses a simple hash-based approach seeded from the user id.
178	function seedUuid(userId: string, label: string): string {
179	  // Create a stable UUID-like identifier from userId + label.
180	  const input = `orma:seed:${userId}:${label}`;
181	  const encoder = new TextEncoder();
182	  const data = encoder.encode(input);
183	
184	  // Simple deterministic hash using FNV-1a extended to 128 bits via four
185	  // independent accumulators, each starting with a different basis.
186	  let h1 = 0x811c9dc5 >>> 0;
187	  let h2 = 0x6c62272e >>> 0;
188	  let h3 = 0x01000193 >>> 0;
189	  let h4 = 0xdeadbeef >>> 0;
190	  for (const b of data) {
191	    h1 = Math.imul(h1 ^ b, 0x01000193) >>> 0;
192	    h2 = Math.imul(h2 ^ b, 0x01000193) >>> 0;
193	    h3 = Math.imul(h3 ^ b, 0x0100019d) >>> 0;
194	    h4 = Math.imul(h4 ^ b, 0x010001a3) >>> 0;
195	  }
196	
197	  // Pack into 16 bytes as hex, then format as UUID.
198	  const raw = [h1, h2, h3, h4]
199	    .map((n) => (n >>> 0).toString(16).padStart(8, "0"))
200	    .join(""); // 32 hex chars
201	
202	  // Set version 4 (byte 6, high nibble) and variant (byte 8, high bits = 10xx).
203	  const chars = raw.split("");
204	  chars[12] = "4"; // version nibble
205	  const variantNibble = (parseInt(chars[16], 16) & 0x3) | 0x8;
206	  chars[16] = variantNibble.toString(16);
207	
208	  const hex = chars.join("");
209	  return [
210	    hex.slice(0, 8),
211	    hex.slice(8, 12),
212	    hex.slice(12, 16),
213	    hex.slice(16, 20),
214	    hex.slice(20, 32),
215	  ].join("-");
216	}
217	
218	// ---------------------------------------------------------------------------
219	// Date helpers
220	// ---------------------------------------------------------------------------
221	
222	/** Returns today's date in the given IANA timezone as YYYY-MM-DD. */
223	function todayInTimezone(tz: string): string {
224	  const now = new Date();
225	  const parts = new Intl.DateTimeFormat("en-CA", {
226	    timeZone: tz,
227	    year: "numeric",
228	    month: "2-digit",
229	    day: "2-digit",
230	  }).format(now);
231	  return parts; // en-CA formats as YYYY-MM-DD
232	}
233	
234	/** Subtracts days from a YYYY-MM-DD date string. */
235	function subtractDays(dateStr: string, days: number): string {
236	  const d = new Date(dateStr + "T12:00:00Z"); // noon to avoid DST issues
237	  d.setUTCDate(d.getUTCDate() - days);
238	  return d.toISOString().slice(0, 10);
239	}
240	
241	/** Returns a timestamptz string for a given date and time in a timezone. */
242	function dateTimeInTz(
243	  dateStr: string,
244	  hour: number,
245	  minute: number,
246	  tz: string,
247	): string {
248	  // Create a date in the specified timezone by finding the UTC offset.
249	  const probe = new Date(`${dateStr}T${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}:00`);
250	  const utcStr = probe.toLocaleString("en-US", { timeZone: "UTC" });
251	  const tzStr = probe.toLocaleString("en-US", { timeZone: tz });
252	  const utcDate = new Date(utcStr);
253	  const tzDate = new Date(tzStr);
254	  const offsetMs = utcDate.getTime() - tzDate.getTime();
255	  const result = new Date(probe.getTime() + offsetMs);
256	  return result.toISOString();
257	}
