259	// ---------------------------------------------------------------------------
260	// Seed data definitions
261	// ---------------------------------------------------------------------------
262	
263	interface SeedPlan {
264	  profile: { id: string; display_name: string; timezone: string };
265	  demoDate: string;
266	  items: Array<{
267	    id: string;
268	    text: string;
