496	async function applyPlan(plan: SeedPlan): Promise<void> {
497	  const userId = plan.profile.id;
498	  const tz = plan.profile.timezone;
499	
500	  console.log("\n=== Applying seed ===");
501	
502	  // 1. Insert items
503	  console.log("Inserting items...");
504	  for (const item of plan.items) {
505	    const sinceDate = subtractDays(plan.demoDate, item.sinceDateDaysAgo);
506	    const createdAt = dateTimeInTz(sinceDate, 9, 0, tz);
507	
508	    const { error } = await supabase
509	      .from("items")
510	      .upsert(
511	        {
512	          id: item.id,
513	          user_id: userId,
514	          text: item.text,
515	          status: "open",
516	          since_date: sinceDate,
517	          source: item.source,
518	          seeded: true,
519	          created_at: createdAt,
520	        },
521	        { onConflict: "id" },
522	      );
523	    if (error) {
524	      console.error(`Failed to insert item "${item.text}":`, error.message);
