528	  }
529	
530	  // 2. Insert call_runs
531	  console.log("Inserting call runs...");
532	  for (const run of plan.runs) {
533	    const scheduledFor = dateTimeInTz(
534	      run.localDate,
535	      run.scheduledHour,
536	      0,
537	      tz,
538	    );
539	    const completedAt = dateTimeInTz(
540	      run.localDate,
541	      run.scheduledHour,
542	      2,
543	      tz,
544	    ); // 2 minutes after scheduled
545	
546	    const { error } = await supabase
547	      .from("call_runs")
548	      .upsert(
549	        {
550	          id: run.id,
551	          user_id: userId,
552	          slot_id: null,
553	          local_date: run.localDate,
554	          part_of_day: run.partOfDay,
555	          scheduled_for: scheduledFor,
556	          state: "completed",
557	          disposition: "answered_extracted",
558	          mood: run.mood,
559	          idempotency_key: run.idempotencyKey,
560	          calle_call_id: `fixture:seed:${run.id.slice(0, 8)}`,
561	          calle_confidence: { score: 0.9, label: "high" },
562	          calle_failure: null,
563	          briefing: null,
564	          dry_run: true,
565	          billable: false,
566	          claimed_at: scheduledFor,
567	          dispatched_at: scheduledFor,
568	          completed_at: completedAt,
569	          terminal_writer: "dry_run",
570	        },
571	        { onConflict: "id" },
572	      );
573	    if (error) {
574	      console.error(`Failed to insert run ${run.localDate}:`, error.message);
575	      Deno.exit(1);
576	    }
577	    console.log(`  ✓ ${run.localDate} ${run.partOfDay} (key: ...${run.idempotencyKey.slice(-12)})`);
578	  }
579	
580	  // 3. Insert transcripts
581	  console.log("Inserting transcripts...");
582	  for (const run of plan.runs) {
583	    const completedAt = dateTimeInTz(
584	      run.localDate,
585	      run.scheduledHour,
586	      2,
587	      tz,
588	    );
589	
590	    const { error } = await supabase
591	      .from("transcripts")
592	      .upsert(
593	        {
594	          call_run_id: run.id,
595	          turns: run.transcript,
596	          raw: { source: "seed" },
597	          fetched_at: completedAt,
598	        },
599	        { onConflict: "call_run_id" },
600	      );
601	    if (error) {
602	      console.error(
603	        `Failed to insert transcript for ${run.localDate}:`,
604	        error.message,
605	      );
606	      Deno.exit(1);
607	    }
608	    console.log(`  ✓ transcript for ${run.localDate}`);
609	  }
610	
611	  // 4. Insert results
612	  console.log("Inserting results...");
613	  for (const run of plan.runs) {
614	    const completedAt = dateTimeInTz(
615	      run.localDate,
616	      run.scheduledHour,
617	      2,
618	      tz,
619	    );
620	
621	    const { error } = await supabase
622	      .from("results")
623	      .upsert(
624	        {
625	          call_run_id: run.id,
626	          structured: run.structuredResult,
627	          valid: true,
628	          error: null,
629	          fetched_at: completedAt,
630	        },
